mapper.select:
SELECT DISTINCT TO_CHAR(t1.TR_YMD, 'YYYY-MM-DD') AS tr_ymd
  FROM SYT0MG t1
 WHERE t1.CORP_GR = #{corpGr}


   AND t1.TR_CD = #{trCd}


   AND t1.TR_CD IN (SELECT ta.TR_CD FROM SZX1PT ta WHERE ta.OBJ_ID = 'W_JA035B3')


 ORDER BY tr_ymd

SELECT NVL(MAX(TR_SEQ), 0)
  FROM SYT0MG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')

   AND FUND_CD = #{fundCd}

SELECT UNIT_AEK
  FROM SYM0YA
 WHERE CORP_GR = #{corpGr}
   AND JM_CD   = #{jmCd}
   AND ROWNUM  = 1

SELECT BANK_CD
  FROM SZX2MM
 WHERE CORP_GR  = #{corpGr}
   AND TR_CO_CD = #{trustee}
   AND ROWNUM   = 1

mapper.insert:
INSERT INTO SYT0MG (
    CORP_GR
  , TR_YMD
  , TR_CD
  , FUND_CD
  , TR_CO_CD
  , TRUSTEE
  , JM_CD
  , TR_SEQ
  , CURRENCY
  , TR_JUSU
  , TR_DANGA
  , TR_COST
  , TR_AEK
  , GYULJE_YMD
  , GYULJE_AEK
  , GYULJE_JM_CD
  , MK_SUIK_PER
  , TRANS_RT
  , PASS_IJA
  , WON_PASS_IJA
  , WON_GYULJE_AEK
  , BS_TYPE
  , FCUR_GYULJE_AEK
  , FCUR_SONIK
  , FCUR_HWAN_CHA
) VALUES (
    #{corpGr, jdbcType=VARCHAR}
  , TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
  , #{trCd, jdbcType=VARCHAR}
  , #{fundCd, jdbcType=VARCHAR}
  , #{trCoCd, jdbcType=VARCHAR}
  , #{trustee, jdbcType=VARCHAR}
  , #{yjCd, jdbcType=VARCHAR}
  , #{trSeq, jdbcType=NUMERIC}
  , #{currency, jdbcType=VARCHAR}
  , NVL(#{trJusu, jdbcType=NUMERIC}, 0)
  , NVL(#{trDanga, jdbcType=NUMERIC}, 0)
  , NVL(#{trCost, jdbcType=NUMERIC}, 0)
  , NVL(#{trAek, jdbcType=NUMERIC}, 0)
  , TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
  , NVL(#{gyuljeAek, jdbcType=NUMERIC}, 0)
  , #{gyuljeJmCd, jdbcType=VARCHAR}
  , #{mkSuikPer, jdbcType=NUMERIC}
  , #{transRt, jdbcType=NUMERIC}
  , #{passIja, jdbcType=NUMERIC}
  , #{wonPassIja, jdbcType=NUMERIC}
  , #{wonGyuljeAek, jdbcType=NUMERIC}
  , NVL(#{bsType, jdbcType=NUMERIC}, 0)
  , #{syt0mgFcurGyuljeAek, jdbcType=NUMERIC}
  , #{syt0mgFcurSonik, jdbcType=NUMERIC}
  , #{syt0mgFcurHwanCha, jdbcType=NUMERIC}
)

mapper.update:
UPDATE SYT0MG
   SET TR_CO_CD        = #{trCoCd, jdbcType=VARCHAR}
     , TRUSTEE         = #{trustee, jdbcType=VARCHAR}
     , JM_CD           = #{yjCd, jdbcType=VARCHAR}
     , CURRENCY        = #{currency, jdbcType=VARCHAR}
     , TR_JUSU         = NVL(#{trJusu, jdbcType=NUMERIC}, 0)
     , TR_DANGA        = NVL(#{trDanga, jdbcType=NUMERIC}, 0)
     , TR_COST         = NVL(#{trCost, jdbcType=NUMERIC}, 0)
     , TR_AEK          = NVL(#{trAek, jdbcType=NUMERIC}, 0)
     , GYULJE_YMD      = TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , GYULJE_AEK      = NVL(#{gyuljeAek, jdbcType=NUMERIC}, 0)
     , GYULJE_JM_CD    = #{gyuljeJmCd, jdbcType=VARCHAR}
     , MK_SUIK_PER     = #{mkSuikPer, jdbcType=NUMERIC}
     , TRANS_RT        = #{transRt, jdbcType=NUMERIC}
     , PASS_IJA        = #{passIja, jdbcType=NUMERIC}
     , WON_PASS_IJA    = #{wonPassIja, jdbcType=NUMERIC}
     , WON_GYULJE_AEK  = #{wonGyuljeAek, jdbcType=NUMERIC}
     , BS_TYPE         = NVL(#{bsType, jdbcType=NUMERIC}, 0)
     , FCUR_GYULJE_AEK = #{syt0mgFcurGyuljeAek, jdbcType=NUMERIC}
     , FCUR_SONIK      = #{syt0mgFcurSonik, jdbcType=NUMERIC}
     , FCUR_HWAN_CHA   = #{syt0mgFcurHwanCha, jdbcType=NUMERIC}
 WHERE CORP_GR = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD  = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD   = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD = #{fundCd, jdbcType=VARCHAR}
   AND TR_SEQ  = #{trSeq, jdbcType=NUMERIC}

